    color: var(--accent);
}

.add-to-cart {
    background-color: var(--bg-tertiary);
    color: var(--text-primary);
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    border: 1px solid var(--border);
    transition: all var(--transition);
}

.add-to-cart:hover {
    background-color: var(--accent);
